result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/parse.ts", "content": "/** Result of parsing a player command in interactive fiction. */
export interface Command {
  verb: string;
  obj: string;
  prep?: string;
  obj2?: string;
}

export interface ParseError {
  error: "unknown-verb" | "empty-input";
  word?: string;
  message: string;
}

export type ParseResult = Command | ParseError;

export function isCommand(r: ParseResult): r is Command {
  return !("error" in r);
}

export function isParseError(r: ParseResult): r is ParseError {
  return "error" in r;
}

/** Verb synonyms, normalized to a canonical verb. */
const VERB_SYNONYMS: Record<string, string> = {
  get: "take",
  grab: "take",
  take: "take",
  pick: "take", // "pick up X" -> handled via UP special case below
  examine: "look-at",
  inspect: "look-at",
  x: "look-at",
  look: "look",
  l: "look",
  put: "put",
  place: "put",
  insert: "put",
  drop: "drop",
  go: "go",
  walk: "go",
  open: "open",
  close: "close",
  read: "read",
};

const ARTICLES = new Set(["the", "a", "an", "my"]);

function stripArticle(word: string): string | null {
  if (!ARTICLES.has(word)) return null;
  const next = ARTICLES.size; // unused; placeholder to keep set referenced
  void next;
  return word;
}

/**
 * Parse "[verb] [object] ([preposition] [object2])?".
 * Articles ("the", "a", ...) are stripped from object phrases.
 * Returns a Command or a structured ParseError.
 */
export function parse(input: string): ParseResult {
  const trimmed = input.trim().toLowerCase();
  if (trimmed === "") {
    return { error: "empty-input", message: "Please enter a command." };
  }

  let tokens = trimmed.split(/\s+/);

  // Canonicalize the verb first so multi-word forms like "pick up" collapse.
  const rawVerb = tokens[0];
  let canonical = VERB_SYNONYMS[rawVerb];
  if (canonical === undefined) {
    return {
      error: "unknown-verb",
      word: rawVerb,
      message: `I don't know how to "${rawVerb}".`,
    };
  }

  tokens = tokens.slice(1);

  // "pick up X" style: swallow a trailing particle right after the verb.
  if (tokens[0] === "up" && canonical === "take") {
    tokens = tokens.slice(1);
  }

  // Split on preposition.
  const PREPS = new Set(["in", "into", "on", "onto", "under", "with", "at"]);
  let prepIndex = -1;
  for (let i = 0; i < tokens.length; i++) {
    if (PREPS.has(tokens[i])) {
      prepIndex = i;
      break;
    }
  }

  const joinObjects = (words: string[]) =>
    words.filter((w) => !ARTICLES.has(w)).join(" ");

  if (prepIndex === -1) {
    return { verb: canonical, obj: joinObjects(tokens) };
  }

  return {
    verb: canonical,
    obj: joinObjects(tokens.slice(0, prepIndex)),
    prep: tokens[prepIndex],
    obj2: joinObjects(tokens.slice(prepIndex + 1)),
  };
}

void stripArticle;
"})
