result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/parse.test.ts", "content": "import { describe, expect, it } from "vitest";
import { isParseError, parse, type ParseResult } from "./parse";

interface Vector {
  name: string;
  input: string;
  want: ParseResult;
}

const vectors: Vector[] = [
  {
    name: "take with article",
    input: "take the brass key",
    want: { verb: "take", obj: "brass key" },
  },
  {
    name: "get synonym",
    input: "get lamp",
    want: { verb: "take", obj: "lamp" },
  },
  {
    name: "grab synonym strips article",
    input: "grab a rusty coin",
    want: { verb: "take", obj: "rusty coin" },
  },
  {
    name: "pick up multi-word verb",
    input: "pick up the lantern",
    want: { verb: "take", obj: "lantern" },
  },
  {
    name: "x abbreviation",
    input: "x lamp",
    want: { verb: "look-at", obj: "lamp" },
  },
  {
    name: "examine synonym",
    input: "examine the old painting",
    want: { verb: "look-at", obj: "old painting" },
  },
  {
    name: "inspect synonym",
    input: "inspect an iron door",
    want: { verb: "look-at", obj: "iron door" },
  },
  {
    name: "put in preposition",
    input: "put coin in slot",
    want: { verb: "put", obj: "coin", prep: "in", obj2: "slot" },
  },
  {
    name: "insert onto strips articles both sides",
    input: "insert the gold coin into the machine",
    want: { verb: "put", obj: "gold coin", prep: "into", obj2: "machine" },
  },
  {
    name: "place on",
    input: "place book on shelf",
    want: { verb: "put", obj: "book", prep: "on", obj2: "shelf" },
  },
  {
    name: "l abbreviation",
    input: "l",
    want: { verb: "look", obj: "" },
  },
  {
    name: "drop simple",
    input: "drop the heavy crate",
    want: { verb: "drop", obj: "heavy crate" },
  },
  {
    name: "walk synonym for go",
    input: "walk north corridor",
    want: { verb: "go", obj: "north corridor" },
  },
  {
    name: "read with my article",
    input: "read my note",
    want: { verb: "read", obj: "note" },
  },
  {
    name: "open no object",
    input: "open",
    want: { verb: "open", obj: "" },
  },
  {
    name: "unknown verb names the word",
    input: "frobnicate the widget",
    want: {
      error: "unknown-verb",
      word: "frobnicate",
      message: 'I don\'t know how to "frobnicate".',
    },
  },
  {
    name: "empty string",
    input: "",
    want: { error: "empty-input", message: "Please enter a command." },
  },
  {
    name: "whitespace only counts as empty",
    input: "   \t  ",
    want: { error: "empty-input", message: "Please enter a command." },
  },
];

describe("parse (table-driven)", () => {
  for (const v of vectors) {
    it(v.name, () => {
      const got = parse(v.input);
      expect(got).toEqual(v.want);
    });
  }

  it("errors are structured, commands are not", () => {
    expect(isParseError(parse("frob x"))).toBe(true);
    expect(isParseError(parse("take sword"))).toBe(false);
  });
});
"})
